public function handle(): int
{
    $expired = 0;

    $trials = Subscription::where('status', 'trial')
        ->where('trial_ends_at', '<', now())
        ->lazy(500);

    foreach ($trials as $subscription) {
        $subscription->update(['status' => 'expired']);
        $expired++;
    }

    $this->info("Expired {$expired} trials.");

    return self::SUCCESS;
}
